-- name: ReapOperations :execrows
WITH doomed AS (
	SELECT operations.id
	FROM operations
	WHERE operations.state = ANY(sqlc.arg(terminal_states)::text[])
		AND operations.finished_at IS NOT NULL
		AND operations.finished_at <= CURRENT_TIMESTAMP - (sqlc.arg(retention_microseconds)::bigint * INTERVAL '1 microsecond')
	ORDER BY operations.id ASC
	LIMIT sqlc.arg(reap_limit)::int
	FOR UPDATE SKIP LOCKED
)
DELETE FROM operations
WHERE operations.id IN (SELECT doomed.id FROM doomed);
